# Frameless React target agent playbook

Use this file as guidance for the installed `@frameless/react` version. The package consumes
`frameless-enriched-ir/2`, emits automatic-runtime JSX, checks generated React conventionality,
and supplies the browser analyzer adapter.

## Target boundaries

1. Import the analyzer lifecycle from `@frameless/react/adapter` in browser projects. That
   subpath contains only the adapter and its browser/runtime dependencies.
2. Keep compiler-enriched IR target-neutral. React lowering, ESTree/Yuku generation, ESLint policy,
   and browser transforms belong in this package.
3. Treat generated JSX as output. Change the enriched IR emitter or gate and regenerate; do not
   hand-edit generated component behavior.

## Conventionality and verification

- Follow the React idiom dossier referenced by each gate policy. Do not suppress the gate with
  ESLint directives or bypass it through helper calls.
- Run `pnpm --dir packages/frameworks/react test` for the offline emitter and gate lanes.
- Run `npx vitest run --project react-browser` for adapter calibration and emitted oracle smoke.
- A package-only pass is not evidence for a consuming application known to be affected.

Yuku pin rule: parser/analyzer/codegen pinned at 0.7.0; any pin change requires re-executing the parity suite (collision families, printer round-trips, gate verdicts) per docs/goals/frameless-composition-v1/notes/yuku-parity-evaluation.md.
import { analyze } from 'yuku-analyzer';
import { generate } from 'yuku-codegen';
import {
	ENRICHED_IR_VERSION,
	FRAMELESS_STATE_GLOBAL,
	type ElementHandleIdrefRecord,
	type EnrichedComponent,
	type EnrichedEventRecord,
	type EnrichedGraphBinding,
	type EnrichedIR,
	type EventHandlerRecord,
	type FramelessPersistenceRecord,
	type ImportedSharedDefinition,
	type SerializableAstNode,
	type SharedDefinition,
	type TemplateNode,
} from '@frameless/compiler';
import * as t from './estree.ts';

const LEGACY_STRING_FIELDS = new Set(['functionSource', 'handlerSources', 'valueSource']);

type StateBinding = EnrichedGraphBinding & { storage: 'state' | 'ref' };
type EmitContext = {
	readonly ir: EnrichedIR;
	readonly componentId: string;
	readonly statesById: ReadonlyMap<string, StateBinding>;
	readonly events: ReadonlyMap<string, EnrichedEventRecord>;
	readonly currentNames: ReadonlyMap<string, string>;
	readonly hookNames: ReadonlyMap<ReactHook, string>;
	readonly nextNames: ReadonlyMap<string, string>;
	readonly setterNames: ReadonlyMap<string, string>;
	readonly setupRefName: string;
	readonly handleNames: ReadonlyMap<string, string>;
	readonly hostRefNames: ReadonlyMap<string, string>;
	/** Hosts carrying an `OverlayRecord`, addressed by node id. */
	readonly overlayHosts: ReadonlySet<string>;
	/**
	 * `boundHostNodeId` -> the minted DOM id that host must carry. One entry per
	 * BOUND HOST rather than per record, so two references to one `el={handle}`
	 * element produce one `id` attribute (see `mintIdrefId`).
	 */
	readonly idrefIds: ReadonlyMap<string, string>;
	/**
	 * `${hostNodeId}\0${attributeName}` -> the id string that IDREF attribute
	 * must spell. Keyed by BOTH halves because one host can carry several IDREF
	 * attributes pointing at different handles.
	 */
	readonly idrefReferences: ReadonlyMap<string, string>;
	readonly edgeRefNames: ReadonlyMap<string, string>;
	readonly sharedPropRoutes: ReadonlyMap<string, SharedPropRoute>;
	readonly edgeSharedProps: ReadonlyMap<string, ReadonlyArray<{ name: string; value: string }>>;
	readonly sharedHookNames: ReadonlyMap<string, string>;
	readonly names: NameAllocator;
	readonly persistenceWrites: { emitted: boolean };
	/**
	 * The local name `createPortal` is imported under, claimed from the same
	 * allocator as the hook names so an authored `createPortal` cannot be
	 * shadowed, and the flag that records whether the import was actually needed.
	 * Two fields rather than one because the NAME must be stable before any
	 * template is walked and the FLAG is only known after the last one is.
	 */
	readonly portalName: string;
	readonly portalUsed: { emitted: boolean };
};
type ReactHook =
	| 'createContext'
	| 'useCallback'
	| 'useContext'
	| 'useRef'
	| 'useState'
	| 'useSyncExternalStore';
type SharedPropRoute = {
	readonly rootComponentId: string;
	readonly consumerComponentIds: ReadonlySet<string>;
	readonly edgeIds: ReadonlySet<string>;
	readonly propName: string;
};
type RenderedNode =
	| t.JSXElement
	| t.JSXExpressionContainer
	| t.JSXFragment
	| t.JSXSpreadChild
	| t.JSXText;

function walk(value: unknown, visit: (record: Record<string, unknown>) => void): void {
	if (!value || typeof value !== 'object') return;
	visit(value as Record<string, unknown>);
	for (const child of Object.values(value)) {
		if (Array.isArray(child)) child.forEach((entry) => walk(entry, visit));
		else walk(child, visit);
	}
}

function visitEstree(
	value: unknown,
	visit: (node: any, parent: any | null) => void,
	parent: any | null = null,
): void {
	if (!value || typeof value !== 'object') return;
	const record = value as Record<string, any>;
	if (typeof record.type === 'string') visit(record, parent);
	for (const [key, child] of Object.entries(record)) {
		if (
			['start', 'end', 'loc', 'comments', 'leadingComments', 'trailingComments'].includes(key)
		)
			continue;
		if (Array.isArray(child)) child.forEach((entry) => visitEstree(entry, visit, record));
		else visitEstree(child, visit, record);
	}
}

function printProgram(program: any): string {
	const result = generate(program, { comments: true, quotes: 'single' });
	if (result.errors.length) {
		throw new Error(
			`yuku-codegen failed: ${result.errors.map((error) => error.message).join('; ')}`,
		);
	}
	return result.code;
}

function printTopLevel(program: any): string {
	const imports = program.body.filter((statement: any) => statement.type === 'ImportDeclaration');
	const declarations = program.body.filter(
		(statement: any) => statement.type !== 'ImportDeclaration',
	);
	return [
		...(imports.length ? [printProgram(t.program(imports))] : []),
		...declarations.map((declaration: any) => printProgram(t.program([declaration]))),
	].join('\n\n');
}

function declaredNames(program: t.Node): string[] {
	const names: string[] = [];
	const pattern = (node: any): void => {
		if (t.isIdentifier(node)) names.push(node.name);
		else if (node?.type === 'AssignmentPattern') pattern(node.left);
		else if (node?.type === 'RestElement') pattern(node.argument);
		else if (node?.type === 'ArrayPattern') node.elements.forEach(pattern);
		else if (node?.type === 'ObjectPattern')
			node.properties.forEach((entry: any) =>
				pattern(entry.type === 'RestElement' ? entry.argument : entry.value),
			);
	};
	visitEstree(program, (node) => {
		if (
			node.type === 'ImportSpecifier' ||
			node.type === 'ImportDefaultSpecifier' ||
			node.type === 'ImportNamespaceSpecifier'
		)
			pattern(node.local);
		else if (node.type === 'VariableDeclarator') pattern(node.id);
		else if (node.type === 'FunctionDeclaration') {
			pattern(node.id);
			node.params.forEach(pattern);
		} else if (node.type === 'FunctionExpression' || node.type === 'ArrowFunctionExpression')
			node.params.forEach(pattern);
	});
	return names.sort();
}

function reanalyzeFunction(
	fn: t.ArrowFunctionExpression,
	transform: (module: ReturnType<typeof analyze>, analyzed: t.ArrowFunctionExpression) => void,
): void {
	const source = printProgram(
		t.program([
			t.variableDeclaration('const', [
				t.variableDeclarator(t.identifier('__framelessHandler'), t.cloneNode(fn, true)),
			]),
		]),
	);
	// `jsx`, AND THE `tsx` FLIP IS REFUSED HERE ON MEASUREMENT.
	//
	// The whole-module OUTPUT VERIFIER below did have to move to `tsx` at
	// `frameless-emitter-capability-v1` T014, because the emitted module now carries
	// an IR-8 props type. THIS SITE IS NOT THAT SITE: it prints ONE handler
	// expression into a throwaway declarator, and a handler expression comes from
	// IR expression nodes that carry no type annotation, so `jsx` is not merely
	// tolerable here - it is the correct grammar.
	//
	// AND THE FLIP IS NOT NEUTRAL, WHICH IS WHY IT IS RECORDED RATHER THAN LEFT
	// UNSAID. MEASURED at yuku-analyzer 0.7.0: an `Identifier` parsed as `jsx` has
	// keys [type, start, end, name]; parsed as `tsx` it additionally carries
	// `decorators: []`, `optional: false` and `typeAnnotation: null`. `equivalent()`
	// compares this re-analyzed AST against nodes this emitter BUILT, which have the
	// bare shape, so flipping this site makes every structural match fail:
	// `reconcileHandlerWrites` then throws "write record absent from handler AST" on
	// SEVEN OF EIGHT SCENARIOS. Measured directly, both ways, before this comment
	// was written. The T014 dispatch listed this site as one that "fires the moment
	// you print a type"; it does not fire, and flipping it breaks the lane.
	const module = analyze(source, { lang: 'jsx', sourceType: 'module', preserveParens: false });
	if (module.diagnostics.length) {
		throw new Error(
			`yuku-analyzer rejected emitted handler: ${module.diagnostics.map((item) => item.message).join('; ')}`,
		);
	}
	const declaration = module.ast.body[0] as any;
	const analyzed = declaration.declarations[0].init as t.ArrowFunctionExpression;
	transform(module, analyzed);
	Object.keys(fn).forEach((key) => delete (fn as any)[key]);
	Object.assign(fn, analyzed);
}

/**
 * THE SCRATCH WRAPPER IS ASYNC ON PURPOSE - see docs/DEFECTS.md entry 12, T047.
 *
 * This builds a throwaway arrow purely to get scope analysis out of
 * `reanalyzeFunction`, splices the transformed node back out, and discards the
 * wrapper - it NEVER reaches output. It used to be synchronous, which meant any
 * statement containing an `await` re-parsed in non-async context, where `await`
 * is a reserved identifier. THE WITNESSED RED, verbatim, on an authored async
 * handler:
 *
 *     yuku-analyzer rejected emitted handler: 'await' is reserved in an
 *     async/module context and cannot be used as an identifier; Expected a
 *     semicolon or an implicit semicolon after a statement, but found 'ready'
 *
 * Thrown from `reanalyzeFunction` <- here <- `replaceVersionReads` <-
 * `toConstSsa`, so the React emitter could not emit ANY handler containing
 * `await`. Measured against the same `yuku-analyzer` the emitter uses:
 *
 *     wrapper async=false: diagnostics=2  unresolved=[]
 *     wrapper async=true:  diagnostics=0  unresolved=[phase,ready]
 *
 * The `unresolved=[]` on the sync wrapper is the part to read twice: had the
 * diagnostic ever been suppressed rather than fixed, free-name replacement would
 * have silently done NOTHING. So the throw above must stay loud.
 *
 * It cannot change any existing output: in `sourceType: 'module'` - which is what
 * `reanalyzeFunction` analyzes under - `await` is ALREADY reserved as an
 * identifier, so no body that parses today parses differently under an async
 * wrapper. The falsifier is cheap and it is in this card's verify:
 * `regenerate.ts` plus `git diff --exit-code -- generated`.
 *
 * The flag is set here rather than in `estree.ts`'s `arrowFunctionExpression`
 * because this is the ONLY wrapper that is thrown away; every other arrow that
 * helper builds is real output whose `async` must stay false.
 */
function replaceFreeNames(node: t.Node, replacements: ReadonlyMap<string, string>): void {
	const statement = t.isStatement(node);
	const fn = t.arrowFunctionExpression(
		[],
		statement ? t.blockStatement([t.cloneNode(node, true)]) : t.cloneNode(node, true),
	);
	fn.async = true;
	reanalyzeFunction(fn, (module) => {
		for (const reference of module.unresolvedReferences) {
			const replacement = replacements.get(reference.name);
			if (!replacement || replacement === reference.name) continue;
			reference.node.name = replacement;
			const parent = module.parentOf(reference.node as any) as any;
			if (parent?.type === 'Property' && parent.shorthand) parent.shorthand = false;
		}
	});
	const replacement = statement ? fn.body.body[0] : fn.body;
	Object.keys(node as any).forEach((key) => delete (node as any)[key]);
	Object.assign(node as any, replacement);
}

/**
 * THE ROW-OWNED ELEMENT HANDLE REFUSAL.
 *
 * `el={row}` inside a keyed `@for` names ONE ELEMENT PER ROW. markless decides
 * that (a bare identifier inside exactly one keyed repeat; every other form is
 * `MARKLESS_ROW_ELEMENT_HANDLE_UNSUPPORTED`) and ships the answer on the record
 * as `rowOwner` + `keyedRepeatScopeIds`.
 *
 * This lane has ONE lowering for an element handle: a component-scoped
 * `useRef(null)` passed as `ref=`. Applied to a row-owned handle that is a
 * single ref cell shared by N rows, last writer wins, and the emitted component
 * compiles, renders and looks right - which is the whole problem. The measured
 * output before this refusal existed was
 *
 *     const row = useRef(null);
 *     … rows.map((item) => <li key={item.id} ref={row}>…</li>)
 *
 * one cell for every row, and with `aria-*` IDREFs one construct away that is
 * silently wrong accessibility rather than a visible break.
 *
 * So the construct is refused BY NAME, with the reason - the same move Qwik
 * makes for `attach=` and `overlay` where it has no in-envelope idiom. Per-row
 * lowering is legitimate future work; SILENT ACCEPTANCE IS NOT, and after this
 * refusal it is unreachable: the fields reach every lane, and a lane that has
 * not decided about them fails on shape instead.
 */
function refuseRowOwnedElementHandle(binding: {
	readonly handleName?: unknown;
	readonly hostNodeId?: unknown;
	readonly rowOwner?: { readonly repeatId?: unknown; readonly keyPath?: unknown };
	readonly keyedRepeatScopeIds?: unknown;
}): void {
	const scopes = binding.keyedRepeatScopeIds;
	if (!binding.rowOwner && !(Array.isArray(scopes) && scopes.length > 0)) return;
	const repeatId =
		(binding.rowOwner?.repeatId as string | undefined) ??
		(Array.isArray(scopes) ? (scopes[0] as string) : 'unknown');
	throw new Error(
		`React emitter does not support a row-owned element handle: el={${String(binding.handleName)}} on ${String(binding.hostNodeId)} is owned by the rows of ${repeatId}, so it names one element per row, and this lane's only element-handle lowering is a component-scoped useRef shared by every row (last writer wins, silently wrong)`,
	);
}

/**
 * The imported-definition table, or the empty table when the IR carries none.
 *
 * The field is omitted rather than emitted empty (see the schema), so ONE
 * accessor normalizes it and every consultation below reads through this. An
 * absent table means "this module imports no shared definition", which makes
 * every dangling check that consults it refuse exactly as it did before.
 */
function importedSharedDefinitionsOf(ir: EnrichedIR): ReadonlyArray<ImportedSharedDefinition> {
	return ir.records.importedSharedDefinitions ?? [];
}

